def design(x, j, k, mode):
    u = x[:, j]
    v = x[:, (j + 2) % 4]
    (a, b) = k
    cols = [np.ones(len(x)), u, v, np.sin(a * u), np.sin(b * v), np.cos(b * v) - 1]
    if mode & 1:
        cols += [np.cos(a * u) - 1]
    if mode & 2:
        cols += [v * v]
    if mode & 4:
        cols += [np.sin(2 * a * u)]
    return np.column_stack(cols)

def fit(x, y, j, mode):
    from scipy.optimize import least_squares

    def f(k, coef=False):
        z = design(x, j, k, mode)
        p = np.linalg.lstsq(z, y, rcond=None)[0]
